import{_ as a,I as t,g as o,j as e}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Движение денежных средств (ДДС)","description":"Как устроен учет реальных денежных потоков, ручные операции и проведение налогов в ОмниКрафт ЕРП.","frontmatter":{"title":"Движение денежных средств (ДДС)","description":"Как устроен учет реальных денежных потоков, ручные операции и проведение налогов в ОмниКрафт ЕРП.","order":10},"headers":[],"relativePath":"ru/docs/spaces/production/dds.md","filePath":"ru/docs/spaces/production/dds.md"}'),s={name:"ru/docs/spaces/production/dds.md"};function l(n,r,i,d,h,c){return t(),o("div",null,[...r[0]||(r[0]=[e('<h1 id="💸-движение-денежных-средств-ддс-контроль-кассы" tabindex="-1">💸 Движение денежных средств (ДДС): Контроль кассы <a class="header-anchor" href="#💸-движение-денежных-средств-ддс-контроль-кассы" aria-label="Permalink to &quot;💸 Движение денежных средств (ДДС): Контроль кассы&quot;">​</a></h1><p>Вкладка <strong>«ДДС»</strong> (Движение денежных средств) отвечает за учет реальных физических денег. Она фиксирует каждую операцию прихода и расхода строго по факту движения средств на ваших счетах или в наличной кассе.</p><p>ДДС показывает движение «живых» денег, помогая не допустить кассового разрыва и точно понимать, сколько вы тратите на сопутствующие нужды.</p><hr><h2 id="📊-главные-показатели-кассы-три-карточки" tabindex="-1">📊 Главные показатели кассы (Три карточки) <a class="header-anchor" href="#📊-главные-показатели-кассы-три-карточки" aria-label="Permalink to &quot;📊 Главные показатели кассы (Три карточки)&quot;">​</a></h2><p>В верхней части экрана выведены ключевые показатели кассового баланса:</p><ol><li><strong>Реальный приход (Касса):</strong> Общая сумма всех денег, которые физически зашли в ваш бизнес (выручка с продаж товаров, предоплаты за индивидуальные заказы, доходы от мастер-классов).</li><li><strong>Реальный расход (Траты):</strong> Все ушедшие из мастерской деньги (оплата сырья, реклама, доставка, аренда, налоги).</li><li><strong>Свободный остаток (Сальдо):</strong> Разница между приходом и расходом на текущую секунду.</li></ol><div class="tip custom-block"><p class="custom-block-title">Почему отрицательное сальдо — это нормально?</p><p>Если в обычном бухучете отрицательный баланс кассы считается грубейшей ошибкой, то в философии ОмниКрафт ЕРП (в рамках <em>смешанных финансов</em>) <strong>отрицательное сальдо ДДС — это нормальный рабочий показатель</strong>.</p><p>Он означает, что на старте или в процессе работы вы инвестировали в проект определенную сумму из личных средств (например, купили лазерный станок или оплатили крупный рулон кожи с личной карты). Программа честно фиксирует этот личный вклад. Как только сальдо ДДС перейдет в зеленый плюс — это сигнал о том, что бизнес полностью окупил все ваши прошлые личные вложения и начал приносить чистый доход.</p></div><hr><h2 id="➕-внесение-прочих-ручных-операции" tabindex="-1">➕ Внесение прочих (ручных) операций <a class="header-anchor" href="#➕-внесение-прочих-ручных-операции" aria-label="Permalink to &quot;➕ Внесение прочих (ручных) операций&quot;">​</a></h2><p>Не все финансовые потоки в бизнесе связаны напрямую со стандартными продажами изделий или закупками кожи. Для учета всех сторонних доходов и расходов предназначена форма <strong>«Внести прочие операции»</strong>.</p><h3 id="_1-выберите-тип-операции" tabindex="-1">1. Выберите тип операции: <a class="header-anchor" href="#_1-выберите-тип-операции" aria-label="Permalink to &quot;1. Выберите тип операции:&quot;">​</a></h3><ul><li><strong>Расход (Траты):</strong> Сторонние издержки вашей мастерской.</li><li><strong>Внереализационный доход:</strong> Деньги, заработанные в рамках деятельности, но не связанные с продажей готовой продукции с витрины.</li></ul><h3 id="_2-укажите-категорию" tabindex="-1">2. Укажите категорию: <a class="header-anchor" href="#_2-укажите-категорию" aria-label="Permalink to &quot;2. Укажите категорию:&quot;">​</a></h3><p>Для точной аналитики выберите одну из системных категорий:</p><ul><li><em>Для расходов:</em> <strong>Реклама</strong> (продвижение, таргет), <strong>Хостинг и Сервисы</strong> (оплата подписок на софт, домен, сайт), <strong>Аренда помещения</strong>, или универсальная категория <strong>Прочее</strong>.</li><li><em>Для доходов:</em> <strong>Мастер-класс</strong> (если вы проводите офлайн или онлайн обучение), <strong>Индивидуальные услуги</strong> (кастомная работа по индивидуальным заказам, ремонт изделий), или <strong>Прочее</strong>.</li></ul><h3 id="_3-сумма-и-комментарии" tabindex="-1">3. Сумма и комментарий: <a class="header-anchor" href="#_3-сумма-и-комментарии" aria-label="Permalink to &quot;3. Сумма и комментарий:&quot;">​</a></h3><ul><li><strong>Умное поле ввода:</strong> При нажатии на поле суммы лишние нули автоматически очищаются, чтобы вам не приходилось тратить время на стирание знаков.</li><li><strong>Комментарий:</strong> Кратко опишите операцию (например, <em>«Реклама в Telegram у блогера»</em> или <em>«Предоплата за кастомную куртку»</em>).</li></ul><h3 id="_4-дата-операции" tabindex="-1">4. Дата операции: <a class="header-anchor" href="#_4-дата-операции" aria-label="Permalink to &quot;4. Дата операции:&quot;">​</a></h3><p>С помощью иконки календаря вы можете провести операцию любым прошлым числом, чтобы восстановить точную историю за прошедший период.</p><hr><h2 id="🧾-специальныи-блок-уплата-налога" tabindex="-1">🧾 Специальный блок: Уплата налога <a class="header-anchor" href="#🧾-специальныи-блок-уплата-налога" aria-label="Permalink to &quot;🧾 Специальный блок: Уплата налога&quot;">​</a></h2><p>Для удобства контроля фискальных трат в программе предусмотрена быстрая форма <strong>«Уплата налога»</strong>.</p><ol><li>Введите сумму налога, которую вы рассчитали и оплатили.</li><li>Программа автоматически спишет эту сумму выбранной датой, присвоит ей категорию <strong>«Налоги»</strong> и добавит соответствующую запись в историю.</li></ol><hr><h2 id="📖-журнал-операции-реестр-кассы" tabindex="-1">📖 Журнал операций (Реестр кассы) <a class="header-anchor" href="#📖-журнал-операции-реестр-кассы" aria-label="Permalink to &quot;📖 Журнал операций (Реестр кассы)&quot;">​</a></h2><p>В левой части экрана расположен детальный журнал движения средств.</p><ul><li>Приходы выделены ярким зеленым цветом со знаком <strong>«+»</strong>, расходы — красным со знаком <strong>«-»</strong>.</li><li>Записи отсортированы в хронологическом порядке от самых свежих к старым.</li><li>Таблица поддерживает пагинацию (постраничный вывод по 20 строк) для плавной и быстрой работы интерфейса без зависаний.</li></ul>',28)])])}const u=a(s,[["render",l]]);export{p as __pageData,u as default};
